let CSL = union isfuzzy=true (CommonSecurityLog | where _IsBillable == true | project BillableBytes = _BilledSize, TimeGenerated, Source = "CommonSecurityLog"), (datatable(BillableBytes:real, TimeGenerated:datetime, Source:string)[]);
let SYS = union isfuzzy=true (Syslog | where _IsBillable == true | project BillableBytes = _BilledSize, TimeGenerated, Source = "Syslog"), (datatable(BillableBytes:real, TimeGenerated:datetime, Source:string)[]);
let Combined = union CSL, SYS
| where isnotempty(BillableBytes)
| where BillableBytes > 0;
let Both = union isfuzzy=true (Combined | where '{TableSource}' == 'Both' or ('{TableSource}' == 'CommonSecurityLog' and Source == 'CommonSecurityLog') or ('{TableSource}' == 'Syslog' and Source == 'Syslog')), (datatable(BillableBytes:real, TimeGenerated:datetime, Source:string)[]);
Both
| summarize TotalGB = sum(BillableBytes) / (1024*1024*1024) by Source
| extend DailyGB = round(TotalGB / iff({TimeRange:grain} contains "d", todouble(replace(@"(\d+)d", @"\1", {TimeRange:grain})), 30), 2)

let Days = iff({TimeRange:grain} contains "d", todouble(replace(@"(\d+)d", @"\1", {TimeRange:grain})), 30.0);
let CSL = union isfuzzy=true (CommonSecurityLog | where _IsBillable == true | project BillableBytes = _BilledSize, Source = "CommonSecurityLog"), (datatable(BillableBytes:real, Source:string)[]);
let SYS = union isfuzzy=true (Syslog | where _IsBillable == true | project BillableBytes = _BilledSize, Source = "Syslog"), (datatable(BillableBytes:real, Source:string)[]);
let Combined = union CSL, SYS
| where isnotempty(BillableBytes) and BillableBytes > 0;
let Filtered = Combined
| where '{TableSource}' == 'Both' or ('{TableSource}' == 'CommonSecurityLog' and Source == 'CommonSecurityLog') or ('{TableSource}' == 'Syslog' and Source == 'Syslog');
Filtered
| summarize TotalGB = sum(BillableBytes) / (1024*1024*1024)
| extend DailyGB = TotalGB / Days
| extend MonthlyCost = round(DailyGB * 30 * todouble('{PricePerGB}'), 2), DailyGB = round(DailyGB, 2)
| project DailyGB, MonthlyCost
